        CHECK( discriminator_field( reachable_receipt, "safe_both" ) == "yes" );
        CHECK( discriminator_field( reachable_receipt, "safe_pair" ) != "none" );
        CHECK( discriminator_field( reachable_receipt, "complete_pairs" ) != "0" );
