            const tripoint_abs_ms selected = selected_positions[index];
            member->setpos( get_map(), get_map().get_bub( selected ) );
            member->goal = camp;
            member->omt_path = fallback_homeward_route;
            member->set_mission( NPC_MISSION_TRAVELLING );
